const needsLogoRefresh = logoStatus.indexOf('needs improvements') > -1;
const needsCampaign = deliverables.indexOf('Campaign Images') > -1;
const needsMoodBoard = deliverables.indexOf('Mood Board') > -1;
const needsCarousels = deliverables.indexOf('Social Media Carousels') > -1;
const scenes = [];
if (needsLogoConcept) {
  scenes.push({ sceneName: brandName + ' - Logo Wordmark', sceneType: 'logo',
    prompt: 'professional wordmark logo for ' + brandName + ' brand, ' + concept + dirNote + ', white background, modern elegant typography, clean minimal design, graphic design presentation, ' + NP });
  scenes.push({ sceneName: brandName + ' - Logo Monogram', sceneType: 'logo',
    prompt: 'monogram lettermark logo for ' + brandName + ', ' + concept + dirNote + ', geometric abstract initials, white background, refined scalable mark, premium brand identity, ' + NP });
  scenes.push({ sceneName: brandName + ' - Logo Icon', sceneType: 'logo',
    prompt: 'icon emblem logo with brand name text for ' + brandName + ', ' + concept + dirNote + ', simple bold symbol, white background, premium feel, professional graphic design, ' + NP });
}
if (needsLogoRefresh) {
  scenes.push({ sceneName: brandName + ' - Logo Refresh Wordmark', sceneType: 'logo',
