    prompt: 'simplified modernized brand icon refresh for ' + brandName + ', ' + concept + dirNote + ', cleaner scalable mark, white background, contemporary design, ' + NP });
}
if (needsCampaign) {
  scenes.push({ sceneName: brandName + ' - Hero Campaign', sceneType: 'campaign',
    prompt: 'cinematic hero campaign photo for ' + brandName + ' brand' + dirNote + ', product textures materials objects, ultra-clean composition, premium editorial aesthetic, dramatic studio lighting, ' + NP });
  scenes.push({ sceneName: brandName + ' - Lifestyle Campaign', sceneType: 'campaign',
    prompt: 'luxury lifestyle brand campaign for ' + brandName + dirNote + ', aspirational objects spaces atmosphere, warm golden editorial photography, premium magazine style, ' + NP });
  scenes.push({ sceneName: brandName + ' - Product Showcase', sceneType: 'campaign',
    prompt: 'minimalist product showcase for ' + brandName + dirNote + ', studio quality lighting, soft shadows, brand-colored background, premium commercial photography, ' + NP });
}
if (needsMoodBoard) {
  scenes.push({ sceneName: brandName + ' - Color Mood Board', sceneType: 'moodboard',
    prompt: 'luxury brand mood board for ' + brandName + dirNote + ', color palette swatches, material textures, props, flat lay editorial composition, refined premium aesthetic, ' + NP });
  scenes.push({ sceneName: brandName + ' - Lifestyle Mood Board', sceneType: 'moodboard',
    prompt: 'curated lifestyle mood board for ' + brandName + dirNote + ', aspirational environments objects details, magazine quality collage, brand world visual identity, ' + NP });
}
if (needsCarousels) {
  scenes.push({ sceneName: brandName + ' - Carousel Hook', sceneType: 'carousel',
    prompt: 'bold Instagram carousel opening slide for ' + brandName + dirNote + ', strong visual hook, product typography brand colors, editorial style, text space, ' + NP });
  scenes.push({ sceneName: brandName + ' - Carousel Value', sceneType: 'carousel',
